    restartFor: string | null;
  };
  view3d: {
    navigation: 'mouse' | 'touchpad';
    zoomToPointer: boolean;
    reverseZoom: boolean;
    freeCamera: boolean;
    leftDrag: DragAction;
    middleDrag: DragAction;
    rightDrag: DragAction;
