        if (st.hover) await page.locator(st.hover).first().hover({ timeout: 3000 });
        if (st.fill) await page.locator(st.fill[0]).first().fill(st.fill[1]);
        if (st.eval) await page.evaluate(st.eval);
        await page.waitForTimeout(st.wait || 250);
